/**
 * Decides whether every named role under `agents/` declares a toolset that can satisfy its task.
 *
 * WHY THIS EXISTS (`delegated-role-toolset-narrower-than-its-contract`). Two SDD agents in a row delivered
 * PARTIAL because their role definition withheld the Bash tool: a role asked to MEASURE cannot, without
 * execution, produce anything but hypotheses wearing the costume of findings. The fix was to add Bash to
 * the planning roles, and the files carrying that fix are regenerated by `gentle-ai sync`, so the fix can
 * be undone silently at any update. This module reads the declared toolsets and refuses a role that needs
 * execution and lacks it, and its selftest runs over the real `agents/` on every landing.
 *
 * THE DECISION. Each role file is classified in `ROLE_POLICY`: it either NEEDS EXECUTION (its task measures
 * or verifies, so it must be able to run a command) or is EXEMPT, with the reason written down. A role file
 * that is classified nowhere is a finding, so a new role forces the question instead of slipping past it.
 * `tools: []` means every tool and satisfies the need. A tool counts only as a whole token: `BashOutput`
 * reads shell output and runs nothing.
 *
 * NO REGEX (M5): `split`, `trim`, `startsWith`, `includes` on literals.
 *
 * @es Decide si cada rol nombrado de `agents/` declara un conjunto de herramientas capaz de cumplir su
 * tarea. Dos agentes SDD seguidos entregaron PARCIAL porque su rol no tenía Bash; el arreglo vive en
 * ficheros que `gentle-ai sync` regenera, así que podía deshacerse en silencio en cualquier actualización.
 * Este módulo lee los conjuntos declarados y rechaza un rol que necesita ejecución y no la tiene. Cada rol
 * se clasifica en `ROLE_POLICY`: necesita ejecución o está EXENTO con el motivo escrito; un rol sin
 * clasificar es un hallazgo. `tools: []` significa todas las herramientas. Una herramienta cuenta solo
 * como token entero: `BashOutput` lee salida y no ejecuta nada.
 */

import { existsSync, readdirSync, readFileSync } from 'node:fs';
import path from 'node:path';

/** The tools that run a command. @es Las herramientas que ejecutan una orden. */
export const EXECUTION_TOOLS = ['Bash', 'PowerShell'];

/** Marker of a role that must be able to run commands. @es Marca de un rol que debe poder ejecutar órdenes. */
export const NEEDS_EXECUTION = 'needs-execution';

/**
 * Every role file and what its task demands. An exempt role carries its reason as a string.
 * @es Cada fichero de rol y lo que exige su tarea. Un rol exento lleva su motivo como texto.
 */
export const ROLE_POLICY = {
  'sdd-init': NEEDS_EXECUTION,
  'sdd-onboard': NEEDS_EXECUTION,
  'sdd-explore': NEEDS_EXECUTION,
  'sdd-propose': NEEDS_EXECUTION,
  'sdd-spec': NEEDS_EXECUTION,
  'sdd-design': NEEDS_EXECUTION,
  'sdd-tasks': NEEDS_EXECUTION,
  'sdd-apply': NEEDS_EXECUTION,
  'sdd-verify': NEEDS_EXECUTION,
  'sdd-archive': NEEDS_EXECUTION,
  'jd-fix-agent': NEEDS_EXECUTION,
  'review-risk': NEEDS_EXECUTION,
  'review-resilience': NEEDS_EXECUTION,
  'review-readability': NEEDS_EXECUTION,
  'review-reliability': NEEDS_EXECUTION,
  'review-refuter': NEEDS_EXECUTION,
  'sdd-research': 'collects external evidence through the web tools and measures nothing in a repository',
  'jd-judge-a': 'blind adversarial judge confined to reading by the judgment-day protocol',
  'jd-judge-b': 'blind adversarial judge confined to reading by the judgment-day protocol',
};

/** The role files present in `agentsDirectory`, as role names. @es Los ficheros de rol presentes, como nombres de rol. */
export function rolesIn(agentsDirectory) {
  return readdirSync(agentsDirectory).filter((name) => name.endsWith('.md')).map((name) => name.slice(0, -'.md'.length)).sort();
}

/** The frontmatter lines of a role file, or `undefined` when it has none. @es Las líneas de frontmatter, o `undefined` si no hay. */
function frontmatterOf(text) {
  const lines = text.split('\n').map((line) => line.trimEnd());
  if (lines[0] !== '---') return undefined;

  const closing = lines.indexOf('---', 1);

  return closing === -1 ? undefined : lines.slice(1, closing);
}

/** The value of `key:` in the frontmatter, or `undefined` when the line is absent. @es El valor de `key:`, o `undefined` si falta. */
function valueOf(frontmatter, key) {
  const line = frontmatter.find((candidate) => candidate.startsWith(`${key}:`));

  return line === undefined ? undefined : line.slice(key.length + 1).trim();
}

/** The tokens of a comma list. @es Los tokens de una lista separada por comas. */
function tokensOf(value) {
  return value.split(',').map((token) => token.trim()).filter((token) => token.length > 0);
}

/**
 * What one role file's declaration means for execution: `'all'` (`tools: []`), `'declared'` with its
 * execution tools, or a `problem` naming why it cannot be read or is blocked.
 * @es Qué significa la declaración de un fichero de rol para la ejecución.
 */
export function executionOf(text) {
  const frontmatter = frontmatterOf(text);
  if (frontmatter === undefined) return { problem: 'has no frontmatter, so its tools cannot be read @es no tiene frontmatter, así que no se leen sus herramientas' };

  const tools = valueOf(frontmatter, 'tools');
  if (tools === undefined) return { problem: 'declares no `tools:` line, so its capability is unverifiable @es no declara `tools:`, así que su capacidad no es verificable' };

  const blocked = tokensOf(valueOf(frontmatter, 'disallowedTools') ?? '').filter((token) => EXECUTION_TOOLS.includes(token));
  if (blocked.length > 0) return { problem: `blocks ${blocked.join(', ')} through \`disallowedTools:\` @es bloquea ${blocked.join(', ')} con \`disallowedTools:\`` };

  if (tools === '[]') return { kind: 'all' };

  return { kind: 'declared', execution: tokensOf(tools).filter((token) => EXECUTION_TOOLS.includes(token)) };
}

/**
 * Every role whose declared toolset cannot satisfy its policy, and every role file nobody classified.
 * @es Cada rol cuyo conjunto declarado no cumple su política, y cada fichero de rol sin clasificar.
 * @param {string} agentsDirectory
 * @returns {{ role: string, problem: string }[]}
 */
export function toolsetGaps(agentsDirectory) {
  if (!existsSync(agentsDirectory)) return [{ role: '(agents)', problem: `directory ${agentsDirectory} is missing @es falta el directorio ${agentsDirectory}` }];

  const present = rolesIn(agentsDirectory);
  const gaps = [];

  for (const role of present) {
    const policy = ROLE_POLICY[role];
    if (policy === undefined) {
      gaps.push({ role, problem: 'is not classified in ROLE_POLICY: decide whether its task needs execution @es no está clasificado en ROLE_POLICY: decide si su tarea necesita ejecución' });
      continue;
    }
    if (policy !== NEEDS_EXECUTION) continue;

    const execution = executionOf(readFileSync(path.join(agentsDirectory, `${role}.md`), 'utf8'));
    if (execution.problem !== undefined) gaps.push({ role, problem: execution.problem });
    else if (execution.kind === 'declared' && execution.execution.length === 0) gaps.push({ role, problem: `needs to run commands but declares none of ${EXECUTION_TOOLS.join(' / ')} @es necesita ejecutar órdenes pero no declara ninguna de ${EXECUTION_TOOLS.join(' / ')}` });
  }

  for (const role of Object.keys(ROLE_POLICY)) {
    if (!present.includes(role)) gaps.push({ role, problem: 'is classified in ROLE_POLICY but its file is missing @es está clasificado en ROLE_POLICY pero falta su fichero' });
  }

  return gaps;
}
